installer-gui-script.script:
function kodiInstalled() {
    if (system.applications.fromIdentifier('org.xbmc.kodi')) return true;
    return system.files.fileExistsAtPath('/Applications/Kodi.app');
}

function kodiRunning() {
    var apps = system.applications.all();
    for (var i = 0; i < apps.length; i++) {
        if (apps[i].bundleIdentifier == 'org.xbmc.kodi') return true;
    }
    return false;
}

function checkKodi() {
    if (!kodiInstalled()) {
        my.result.type = 'Fatal';
        my.result.title = system.localizedString('KODI_MISSING_TITLE');
        my.result.message = system.localizedString('KODI_MISSING_MESSAGE');
        return false;
    }
    if (kodiRunning()) {
        my.result.type = 'Fatal';
        my.result.title = system.localizedString('KODI_RUNNING_TITLE');
        my.result.message = system.localizedString('KODI_RUNNING_MESSAGE');
        return false;
    }
    return true;
}
